import{z as B,x as s,o as t,c as p,q as i,j as r,D as n,d as e,s as A,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"理性疏忽","description":"","frontmatter":{"title":"理性疏忽","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/rational-inattention.md","filePath":"econ/rational-inattention.md","lastUpdated":1791413859000}'),d={name:"econ/rational-inattention.md"};function m(h,a,c,f,F,u){const o=s("Mermaid");return t(),p("div",null,[a[2]||(a[2]=i('<h1 id="理性疏忽" tabindex="-1">理性疏忽 <a class="header-anchor" href="#理性疏忽" aria-label="Permalink to &quot;理性疏忽&quot;">​</a></h1><div class="epigraph"><p>注意力是有限信道；最优编码使人对重要、易变的变量反应更灵敏，对其余变量近乎不更新。</p><footer>—— Sims, Implications of Rational Inattention, JME 2003；Maćkowiak and Wiederholt, Optimal Sticky Prices under Rational Inattention, AER 2009</footer></div><p><a href="/econ/sticky-information">上一课</a>的 \\(\\lambda\\) 是外生更新率。本课缺口是<strong>内生注意力</strong>：Shannon 容量下的最优信号。不把 \\(\\lambda\\) 再估一遍，不写神经网络注意力层。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Sims：人不是每期免费看见状态，而是选择一个关于状态的信号，互信息受容量约束。结果：对小的、不重要的冲击几乎不反应，对大的冲击反应；预测误差与宏观惯性内生。Maćkowiak–Wiederholt：企业把有限注意力在总需求与特异需求之间分配，加总价格对货币更粘、对特异更灵活——与微观价格频繁改动、宏观通胀惯性可并存。缺口是把粘性信息的外生 \\(\\lambda\\) 换成最优信道，而不是再写一次 vintage 加权。</p><p><span class="marginnote">术语翻译：理性疏忽就是「看不过来，所以有选择地看」。不是看不见，而是带宽（容量 \\(\\kappa\\)）有限，你把清晰度分给最重要的东西，其余只看个模糊轮廓——而且这种分配本身是算过账的。</span></p><p><span class="marginnote">Sims, <em>JME</em> 2003。Maćkowiak and Wiederholt, <em>AER</em> 2009。Woodford 的不完全信息定价。Caplin、Dean、Angeletos 等后续。Shannon 是常用的 tractable 约束，不是唯一认知模型。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>代理人最大化效用减注意力成本（或受 \\(I(X;S)\\le\\kappa\\)）。高斯二次时线性信号最优，Kalman 增益由容量决定。宏观：容量 \\(\\kappa\\) 校准到调查误差或 IRF。政策：更嘈杂的政策规则浪费容量，透明规则节省注意力——接到沟通课。与 HANK：穷人可能把容量全用在流动性，不跟踪利率路径，直接欧拉通道更弱。</p><p><span class="marginnote">数字实例：容量以比特计。若 \\(\\kappa=1\\) 比特（约一次「是/否」判断的信息量）要在「盯通胀」与「盯利率」之间分配：平均各摊半比特，两件事都只能看得雾；全给通胀，则通胀看得清、利率几乎不更新——预期数据里的迟钝就是这么来的。</span></p>',10)),(t(),r(l,null,{default:n(()=>[A(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20KAP%5B%22%E5%AE%B9%E9%87%8F%20%CE%BA%22%5D%20--%3E%20SIG%5B%22%E6%9C%80%E4%BC%98%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20SIG%20--%3E%20GAIN%5B%22%E5%AF%B9%E9%87%8D%E8%A6%81%E5%86%B2%E5%87%BB%E9%AB%98%E5%A2%9E%E7%9B%8A%22%5D%0A%20%20GAIN%20--%3E%20MICRO%5B%22%E5%BE%AE%E8%A7%82%E5%8F%AF%E7%81%B5%E6%B4%BB%22%5D%0A%20%20GAIN%20--%3E%20MACRO%5B%22%E5%AE%8F%E8%A7%82%E5%AF%B9%E6%80%BB%E9%87%8F%E6%9B%B4%E7%B2%98%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"与学习：疏忽是每期最优压缩；学习是参数递推。与诊断性：疏忽是噪声，诊断性是偏误（后课）。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[e("机制是稀缺注意力的配置。价格系统若已充分统计，本可节省注意力（Hayek）；一旦价格嘈杂或策略互补强（美容竞赛），每人仍须浪费容量猜别人——Angeletos–La’O、Morris–Shin 的高阶信念接口。本课程不重写"),E("a",{href:"/econ/beauty-contest-higher-order"},"美容竞赛"),e("全文，只借用：疏忽加策略互补 ⇒ 更大惯性。")],-1)),(t(),r(l,null,{default:n(()=>[A(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20FIRM%5B%22%E4%BC%81%E4%B8%9A%E7%9A%84%E5%AE%B9%E9%87%8F%20%CE%BA%22%5D%20--%3E%20Q%5B%22%E6%B3%A8%E6%84%8F%E5%8A%9B%E5%BE%80%E5%93%AA%E6%94%BE%3F%22%5D%0A%20%20Q%20--%3E%20AGG%5B%22%E7%9B%AF%E6%80%BB%E9%87%8F%3A%20%E8%A6%81%E8%AF%BB%E6%87%82%E6%94%BF%E7%AD%96%E4%B8%8E%E7%BB%8F%E6%B5%8E%E5%91%A8%E6%9C%9F%22%5D%0A%20%20Q%20--%3E%20IDIO%5B%22%E7%9B%AF%E8%87%AA%E5%AE%B6%E9%A1%BE%E5%AE%A2%3A%20%E7%9B%B4%E6%8E%A5%E5%86%B3%E5%AE%9A%E5%88%A9%E6%B6%A6%22%5D%0A%20%20IDIO%20--%3E%20MICRO%5B%22%E8%87%AA%E5%AE%B6%E4%BB%B7%E6%A0%BC%E5%8F%8D%E5%BA%94%E5%BF%AB%22%5D%0A%20%20AGG%20--%3E%20STICKY%5B%22%E5%AF%B9%E6%80%BB%E9%87%8F%E5%8F%8D%E5%BA%94%E6%85%A2%2C%20%E5%8A%A0%E6%80%BB%E9%80%9A%E8%83%80%E7%B2%98%22%5D%0A%20%20MICRO%20--%3E%20OBS%5B%22%E4%B8%8E%E5%BE%AE%E8%A7%82%E4%BB%B7%E6%A0%BC%E9%A2%91%E7%B9%81%E6%94%B9%E5%8A%A8%E7%9A%84%E8%A7%82%E5%AF%9F%E5%B9%B6%E5%AD%98%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p>容量随激励变：高通胀时人更跟踪 CPI（经验上预期更「解锚」前的更新），这是后课锚定的微观基础之一。</p><p><span class="marginnote">本课不把信息论当宏观的第一性原理重讲。互信息是约束的方便写法。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不定 \\(\\kappa\\) 的生理值。不把菜单成本与疏忽混成一个参数。资产定价里的疏忽（对新闻反应不足）可点名，不估计横截面。Transformer 与机器学习注意力禁止写入本栏。</p><p><span class="marginnote">常见误区：初学者容易把理性疏忽当成「非理性偷懒」。恰恰相反——疏忽是优化的结果：对影响小的事少花带宽，总效用比样样都盯更高。真正「不理性」的是乱分配注意力，不是省着用。</span></p><p>后课默认：更新率可以是最优注意力配置的结果。下一课：偏差不是噪声，而是对新闻的过度反应——诊断性预期。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>理性疏忽：容量约束下的最优信号。</li><li>可同时解释微观灵活与宏观惯性。</li><li>与外生 \\(\\lambda\\)、与学习、与认知偏差分列。</li><li>出处：Sims, <em>JME</em> 2003。</li></ul>',8))])}const I=B(d,[["render",m]]);export{D as __pageData,I as default};
